module browserjs

import html

fn test_public_webgl_extension_prototypes_use_source_receivers_and_unexposed_interfaces() {
	$if !darwin {
		return
	}
	mut document := html.parse_document('<canvas></canvas>')
	mut host := CanvasWebGLHost.create(document)
	mut runtime := Runtime.create()
	defer { runtime.close() }
	host.install(mut runtime)!
	runtime.evaluate_host('const __canvases=Object.create(null);function __canvasFor(s){return __canvases[s.bridgeKey]||(__canvases[s.bridgeKey]={state:s});}function __canvasDimension(s,key){return s[key];}function __element(s){return {state:s};}')!
	runtime.evaluate_host(webgl_bootstrap())!
	runtime.evaluate_host(r'const a=__webglContext({bridgeKey:"__created_extension_a",width:2,height:2},"webgl",{preserveDrawingBuffer:true}),b=__webglContext({bridgeKey:"__created_extension_b",width:2,height:2},"webgl",{preserveDrawingBuffer:true}),aAngle=a.getExtension("ANGLE_instanced_arrays"),bAngle=b.getExtension("ANGLE_instanced_arrays"),aOes=a.getExtension("OES_vertex_array_object"),bOes=b.getExtension("OES_vertex_array_object"),draw=a.getExtension("WEBGL_draw_buffers");')!
	assert runtime.evaluate_host(r'(function(){if(!aAngle||!bAngle||!aOes||!bOes||!draw||typeof ANGLEInstancedArrays!=="undefined"||typeof OESVertexArrayObject!=="undefined"||typeof WebGLDrawBuffers!=="undefined")return false;for(const [first,second,name] of [[aAngle,bAngle,"ANGLEInstancedArrays"],[aOes,bOes,"OESVertexArrayObject"]]){if(Object.getPrototypeOf(first)!==Object.getPrototypeOf(second)||first===second||Object.keys(first).length!==0||Object.getPrototypeOf(Object.getPrototypeOf(first))!==Object.prototype||Object.prototype.toString.call(first)!=="[object "+name+"]")return false}if(a.getExtension("angle_instanced_arrays")!==aAngle||aAngle.vertexAttribDivisorANGLE!==bAngle.vertexAttribDivisorANGLE||aAngle.vertexAttribDivisorANGLE.name!=="vertexAttribDivisorANGLE"||aAngle.vertexAttribDivisorANGLE.length!==2)return false;const descriptor=Object.getOwnPropertyDescriptor(Object.getPrototypeOf(aAngle),"VERTEX_ATTRIB_ARRAY_DIVISOR_ANGLE"),method=Object.getOwnPropertyDescriptor(Object.getPrototypeOf(aAngle),"vertexAttribDivisorANGLE");return descriptor.value===0x88fe&&descriptor.enumerable&&!descriptor.writable&&!descriptor.configurable&&method.enumerable&&method.writable&&method.configurable&&!Object.prototype.hasOwnProperty.call(method.value,"prototype")&&Object.prototype.toString.call(draw)==="[object WebGLDrawBuffers]"})()')! == 'true'
	assert runtime.evaluate_host(r'(function(){aAngle.vertexAttribDivisorANGLE.call(bAngle,1,3);return a.getVertexAttrib(1,aAngle.VERTEX_ATTRIB_ARRAY_DIVISOR_ANGLE)===0&&b.getVertexAttrib(1,bAngle.VERTEX_ATTRIB_ARRAY_DIVISOR_ANGLE)===3&&a.getError()===a.NO_ERROR&&b.getError()===b.NO_ERROR})()')! == 'true'
	assert runtime.evaluate_host(r'(function(){const array=bOes.createVertexArrayOES();aOes.bindVertexArrayOES.call(bOes,array);return a.getParameter(aOes.VERTEX_ARRAY_BINDING_OES)===null&&b.getParameter(bOes.VERTEX_ARRAY_BINDING_OES)===array&&aOes.isVertexArrayOES.call(bOes,array)&&a.getError()===a.NO_ERROR&&b.getError()===b.NO_ERROR})()')! == 'true'
	assert runtime.evaluate_host(r'(function(){let converted=0;const number={valueOf(){converted++;throw "converted"}};for(const receiver of [{},aOes,Object.create(Object.getPrototypeOf(aAngle)),null]){try{aAngle.vertexAttribDivisorANGLE.call(receiver,1,number);return false}catch(error){if(!(error instanceof TypeError)||error.message!=="Not an object of type ANGLEInstancedArrays")return false}}try{draw.drawBuffersWEBGL.call(aAngle,{get [Symbol.iterator](){converted++;throw "iterator"}});return false}catch(error){if(error.message!=="Not an object of type WebGLDrawBuffers")return false}try{aAngle.vertexAttribDivisorANGLE(1);return false}catch(error){if(error.message!=="vertexAttribDivisorANGLE() needs 2 arguments")return false}try{(function(){"use strict";aAngle.VERTEX_ATTRIB_ARRAY_DIVISOR_ANGLE=0})();return false}catch(error){return error instanceof TypeError&&converted===0&&a.getError()===a.NO_ERROR&&b.getError()===b.NO_ERROR}})()')! == 'true'
	assert runtime.evaluate_host(r'(function(){const types={EXT_blend_minmax:"EXTBlendMinMax",EXT_texture_filter_anisotropic:"EXTTextureFilterAnisotropic",OES_element_index_uint:"OESElementIndexUint",OES_standard_derivatives:"OESStandardDerivatives",WEBGL_compressed_texture_s3tc:"WebGLCompressedTextureS3tc",WEBGL_compressed_texture_s3tc_srgb:"WebGLCompressedTextureS3tcSrgb",WEBGL_debug_renderer_info:"WebGLDebugRendererInfo"};let queried=0;for(const name of Object.keys(types)){const extension=a.getExtension(name);if(extension===null)continue;queried++;if(typeof globalThis[types[name]]!=="undefined"||Object.prototype.toString.call(extension)!=="[object "+types[name]+"]"||Object.keys(extension).length!==0)return false}return queried>0&&a.getError()===a.NO_ERROR})()')! == 'true'
}
